-- FASE D · Bloque 4 · Datos completos para Mateo, Marcos y Lucas
-- Complementa 20260802085000_contexto_evangelios_sinopticos.sql.

with source as(select id from public.biblical_sources where slug='vida-contexto-editorial'),
data(slug,book_code,scope_kind,chapter_start,chapter_end,title,summary,historical_context,jewish_context,literary_context,authorial_intent,theological_reflection,interpretive_cautions,key_terms,people_groups,places) as(values
('mateo-perfil','MAT','book',1,28,'Mateo: Jesús, Israel y el reino de los cielos','Mateo presenta a Jesús como Mesías, maestro autorizado e Hijo de Dios, organiza su enseñanza en grandes discursos y narra su misión desde Israel hacia todas las naciones.','El evangelio surge en un ambiente judío del siglo I bajo dominio romano y refleja debates sobre identidad, Torá, sinagoga y formación comunitaria después de la destrucción del templo. La fecha y localización exactas son debatidas.','Mateo utiliza intensamente las Escrituras de Israel, genealogía, Moisés, reino de los cielos y fórmulas de cumplimiento. Las controversias internas no deben transformarse en oposición entre cristianismo y judaísmo como religiones totalmente separadas.','Narración y cinco grandes discursos se alternan. Inclusiones entre Emanuel y la presencia final, montañas, cumplimiento y discipulado crean unidad.','Mostrar que en Jesús el reino se hace visible mediante enseñanza, compasión, justicia y una comunidad enviada a formar discípulos.','Seguir a Jesús une obediencia, misericordia y presencia. La autoridad del Mesías no elimina la Torá como historia de Israel, sino que la interpreta desde el amor a Dios y al prójimo.','Los «judíos» o fariseos no deben presentarse como caricatura de todo el pueblo judío. Las fórmulas de cumplimiento requieren contexto y no significan que cada texto antiguo fuera una predicción aislada. Mateo 27 no autoriza acusación colectiva antijudía.',ARRAY['Mateo','reino de los cielos','cumplimiento','Torá','discípulos','Emanuel']::text[],ARRAY['judíos','discípulos','fariseos','romanos','naciones']::text[],ARRAY['Galilea','Jerusalén','Belén','Egipto']::text[]),
('mateo-1-4-origen-mision','MAT','section',1,4,'Genealogía, nacimiento, desierto e inicio en Galilea','La genealogía vincula a Jesús con Abraham y David; relatos de nacimiento, huida y retorno interpretan su historia mediante Israel, y bautismo y tentación preparan el anuncio del reino.','Herodes el Grande gobernó bajo Roma. La movilidad entre Judea, Egipto y Galilea refleja rutas y peligros políticos de la época.','La genealogía incluye mujeres y episodios complejos de Israel. Las citas de cumplimiento usan métodos interpretativos judíos que releen patrones de la Escritura.','Dos capítulos de origen son seguidos por Juan el Bautista, bautismo, tentación y llamado de discípulos. Motivos de éxodo y Moisés son notorios.','Presentar a Jesús dentro de la historia de Israel y mostrar que su misión inicia con identidad recibida, prueba y llamado a una nueva forma de vida.','La identidad no depende de una genealogía idealizada: Mateo conserva historias irregulares dentro de la línea mesiánica. La misión comienza desde la fidelidad, no desde espectáculo.','Los magos no son descritos como tres reyes y la estrella no debe usarse para astrología. La matanza de niños no debe narrarse de forma gráfica. La tentación no implica que toda dificultad sea una prueba directa diseñada por Dios.',ARRAY['genealogía','Abraham','David','Emanuel','bautismo','tentación','Galilea']::text[],ARRAY['familia de Jesús','magos','Herodes','discípulos','judíos']::text[],ARRAY['Belén','Egipto','Nazaret','Jordán','Galilea']::text[]),
('mateo-5-7-sermon','MAT','section',5,7,'Sermón del monte y justicia del reino','Bienaventuranzas, enseñanza sobre Torá, oración, economía, relaciones y discernimiento describen una justicia interior y comunitaria que supera la exhibición religiosa.','La vida campesina, deudas, tribunales, patronazgo y ocupación romana están detrás de ejemplos sobre millas, túnicas, impuestos y enemigos.','Jesús habla como maestro judío e interpreta la Torá. «Cumplir» no significa abolir y la oración modelo se relaciona con formas judías de santificación del nombre y petición del reino.','Tres capítulos organizan bendiciones, antítesis, prácticas religiosas y una conclusión de dos caminos y dos fundamentos.','Formar discípulos cuyo carácter y relaciones hagan visible el reino mediante reconciliación, integridad, generosidad y confianza.','La espiritualidad no necesita espectáculo. La oración sincera, el cuidado del prójimo y la verdad cotidiana forman una vida estable.','«No juzguen» no prohíbe todo discernimiento ni denunciar abuso. «Poner la otra mejilla» no exige permanecer en peligro. Las enseñanzas sobre divorcio deben leerse protegiendo a personas vulnerables y no como condena automática.',ARRAY['bienaventuranzas','Torá','oración','Padre nuestro','enemigos','justicia','roca']::text[],ARRAY['discípulos','pobres','autoridades','familias']::text[],ARRAY['Galilea','monte']::text[]),
('mateo-8-13-obras-parabolas','MAT','section',8,13,'Autoridad, compasión y parábolas del reino','Milagros, llamados y controversias muestran autoridad compasiva; el envío de los Doce y las parábolas explican una misión que encuentra recepción, oposición y crecimiento oculto.','Enfermedad, exclusión ritual, deudas y agricultura condicionaban la vida. Los exorcismos pertenecen al lenguaje religioso del siglo I y no sustituyen diagnósticos médicos modernos.','La limpieza de personas excluidas, el sábado y la mesa se debaten dentro de marcos judíos. Las parábolas usan Escritura y sabiduría cotidiana para provocar discernimiento.','Colecciones de acciones y discursos culminan en siete parábolas del capítulo 13, donde semilla, levadura, tesoro y red presentan distintos aspectos del reino.','Mostrar que la autoridad de Jesús restaura y envía, y que el reino puede crecer de formas pequeñas sin imponerse por fuerza.','La compasión precede al envío. Una comunidad madura aprende a reconocer fruto sin exigir resultados inmediatos ni confundir oposición con fracaso.','No debe afirmarse que toda enfermedad tiene causa demoníaca. Las parábolas no son códigos secretos con una equivalencia fija para cada detalle. La misión a Israel en un momento narrativo no autoriza exclusión étnica posterior.',ARRAY['milagros','compasión','Doce','parábolas','semilla','reino','sábado']::text[],ARRAY['discípulos','enfermos','fariseos','multitudes','gentiles']::text[],ARRAY['Galilea','Capernaúm','lago']::text[]),
('mateo-14-20-identidad-comunidad','MAT','section',14,20,'Identidad mesiánica, comunidad y camino hacia Jerusalén','Alimentaciones, controversias, confesión de Pedro, transfiguración y enseñanzas comunitarias preparan el viaje hacia Jerusalén y redefinen grandeza como servicio.','Las aldeas de Galilea y regiones gentiles formaban un paisaje diverso. Honor, patronazgo, jerarquía familiar y deudas aparecen en enseñanzas comunitarias.','La confesión mesiánica se relaciona con expectativas judías variadas. Mateo 18 trata cuidado de pequeños, corrección, perdón y restauración comunitaria.','Dos ciclos de alimentación y señales conducen al giro de Cesarea de Filipo; después anuncios de sufrimiento se alternan con incomprensión de discípulos.','Enseñar que reconocer al Mesías implica aceptar un liderazgo servidor, proteger al vulnerable y practicar perdón responsable.','La autoridad comunitaria existe para cuidar y restaurar, no para controlar. Perdonar no elimina verdad, límites ni procesos de justicia.','«Atar y desatar» refleja autoridad interpretativa y comunitaria, no poderes mágicos. El proceso de Mateo 18 no debe manejar delitos graves únicamente de forma privada ni usarse para presionar reconciliación insegura.',ARRAY['Pedro','Mesías','transfiguración','pequeños','perdón','servicio','Jerusalén']::text[],ARRAY['discípulos','niños','familias','gentiles','fariseos']::text[],ARRAY['Galilea','Cesarea de Filipo','Jerusalén']::text[]),
('mateo-21-28-pasion-mision','MAT','section',21,28,'Jerusalén, pasión, resurrección y misión','Jesús entra en Jerusalén, confronta autoridades y templo, enseña sobre vigilancia, comparte la cena, es ejecutado por Roma, resucita y envía a sus discípulos a todas las naciones.','La Pascua reunía peregrinos bajo vigilancia romana. La crucifixión era una pena imperial. Autoridades sacerdotales y prefectura romana participaron dentro de relaciones complejas de poder.','Las controversias son disputas judías internas. La cena se relaciona con Pascua y pacto; la resurrección transforma la derrota en comienzo de misión.','La confrontación pública conduce a discursos escatológicos, pasión y una conclusión en Galilea que retoma autoridad y presencia.','Mostrar que el reinado de Jesús se revela mediante servicio y entrega, que la violencia imperial no posee la última palabra y que la misión forma comunidades obedientes.','La resurrección no borra las heridas ni la responsabilidad histórica; abre esperanza y envío. La presencia prometida acompaña una misión sin coerción.','No debe culparse colectivamente al pueblo judío por la crucifixión. Mateo 24 no ofrece una cronología simple del fin. La gran comisión no autoriza conquista cultural, colonialismo ni bautismos forzados.',ARRAY['Jerusalén','templo','Pascua','crucifixión','resurrección','gran comisión']::text[],ARRAY['discípulos','autoridades sacerdotales','romanos','multitudes','naciones']::text[],ARRAY['Jerusalén','Getsemaní','Gólgota','Galilea']::text[]),
('marcos-perfil','MRK','book',1,16,'Marcos: el Mesías servidor y el camino de la cruz','Marcos presenta con urgencia a Jesús anunciando el reino, actuando con autoridad y conduciendo a discípulos lentos para comprender hacia una cruz que redefine poder y una resurrección que abre misión.','El evangelio refleja un mundo bajo poder romano y probablemente una comunidad que conocía oposición. Su fecha y ubicación exactas son debatidas, frecuentemente alrededor de la guerra judía del 66–70.','Jesús y sus primeros seguidores son judíos; debates sobre pureza, sábado y templo ocurren dentro del judaísmo del Segundo Templo.','Dos mitades giran alrededor de la confesión de Pedro: autoridad en Galilea y camino hacia Jerusalén. El secreto, la incomprensión y el final abrupto producen participación del lector.','Revelar que la identidad de Jesús solo se comprende plenamente desde servicio, sufrimiento y entrega, no desde triunfo sin cruz.','La buena noticia forma personas que siguen aun con temor e incomprensión. La grandeza se mide por servicio y recepción de quienes tienen menor estatus.','El final antiguo más corto en 16:8 y los finales posteriores deben explicarse textualmente. Los exorcismos no autorizan diagnosticar trastornos. La cruz no debe usarse para exigir que víctimas toleren abuso.',ARRAY['Marcos','Hijo de Dios','secreto','servicio','cruz','discipulado','resurrección']::text[],ARRAY['discípulos','multitudes','fariseos','romanos','mujeres discípulas']::text[],ARRAY['Galilea','Jerusalén','Capernaúm']::text[]),
('marcos-1-8-galilea','MRK','section',1,8,'Reino y autoridad en Galilea','Jesús anuncia el reino, llama discípulos, sana y enseña, enfrenta controversias y alimenta multitudes, mientras la pregunta sobre su identidad aumenta.','Galilea estaba bajo Herodes Antipas y conectada con economía pesquera, aldeas y ciudades helenizadas. Enfermedad podía traer exclusión económica y social.','Las controversias sobre sábado, pureza y tradición son debates judíos. Marcos 7 debe leerse con atención textual antes de concluir que toda práctica alimentaria judía fue abolida en ese momento.','Escenas rápidas de autoridad se agrupan con parábolas, viajes en barco y dos alimentaciones hasta la confesión de Pedro.','Mostrar que el reino restaura personas y atraviesa fronteras, pero que presenciar poder no garantiza comprender la identidad ni el camino de Jesús.','La compasión atiende cuerpo, comunidad y dignidad. La fe puede pedir ayuda sin convertirse en mérito que compra un milagro.','No debe prometerse sanidad física por repetir acciones del relato. «Tu fe te ha salvado» no culpa a quien no mejora. Los debates de pureza no autorizan desprecio hacia prácticas judías.',ARRAY['reino','Galilea','autoridad','sanidad','pureza','pan','Pedro']::text[],ARRAY['discípulos','enfermos','fariseos','gentiles','multitudes']::text[],ARRAY['Galilea','Capernaúm','lago','Decápolis']::text[]),
('marcos-8-10-camino','MRK','section',8,10,'Confesión, cruz y discipulado en el camino','Después de la confesión de Pedro, Jesús anuncia tres veces su sufrimiento y corrige ambiciones, enseñando sobre negarse a sí mismo, recibir niños, riqueza y servicio.','La crucifixión era símbolo de humillación y dominio romano. Honor, estatus, riqueza y redes patronales configuraban expectativas sobre un líder victorioso.','La expectativa mesiánica no era única. Marcos confronta una comprensión del Mesías separada del sufrimiento y de la entrega por otros.','Tres anuncios de pasión están seguidos por incomprensión y enseñanza, formando una estructura pedagógica en el camino.','Formar discípulos que acepten que el poder de Jesús no imita al imperio y que la vida comunitaria protege a pequeños y sirve en vez de dominar.','Negarse a sí mismo significa renunciar al ego como centro, no negar dignidad, necesidades o seguridad. El servicio cristiano no convierte a nadie en objeto de explotación.','Tomar la cruz no obliga a permanecer en abuso ni buscar sufrimiento. La enseñanza al hombre rico no debe generalizarse como una única instrucción económica idéntica para todos sin conservar su desafío real a la riqueza.',ARRAY['Pedro','camino','cruz','niños','riqueza','servicio','rescate']::text[],ARRAY['discípulos','niños','ricos','pobres']::text[],ARRAY['Cesarea de Filipo','camino a Jerusalén']::text[]),
('marcos-11-16-jerusalen','MRK','section',11,16,'Jerusalén, cruz y tumba vacía','La entrada en Jerusalén y la acción en el templo conducen a controversias, discurso de vigilancia, cena, arresto, juicio, crucifixión y anuncio de resurrección en una tumba vacía.','Jerusalén en Pascua estaba bajo control romano. El templo era centro religioso y económico; la ejecución por crucifixión correspondía a autoridad imperial.','El velo, la confesión del centurión y las mujeres en la tumba reinterpretan identidad y acceso. Las autoridades del relato no representan a todo el pueblo judío.','La pasión ocupa una proporción extensa del evangelio. El final en 16:8 deja temor y anuncio pendientes de respuesta del lector.','Mostrar que Jesús enfrenta poder religioso e imperial sin reproducir su violencia y que la resurrección convierte el aparente fracaso en llamado a continuar.','La fidelidad puede incluir permanecer, observar y cuidar cuando otros huyen. El temor no invalida la misión, pero necesita ser atravesado por la noticia de vida.','Marcos 13 no permite fijar fechas. El grito de abandono no debe usarse para afirmar ruptura metafísica sin reconocer su vínculo con Salmo 22. Deben distinguirse 16:8 y finales manuscritos posteriores.',ARRAY['templo','Pascua','cena','cruz','centurión','mujeres','tumba vacía']::text[],ARRAY['discípulos','mujeres','autoridades sacerdotales','romanos']::text[],ARRAY['Jerusalén','Getsemaní','Gólgota','tumba']::text[]),
('lucas-perfil','LUK','book',1,24,'Lucas: salvación, Espíritu y reversión social','Lucas ofrece un relato ordenado de Jesús desde promesas a Israel hasta resurrección, destacando oración, Espíritu Santo, mujeres, pobres, pecadores, samaritanos y una salvación destinada a todos los pueblos.','El evangelio se sitúa en el mundo romano del siglo I y forma la primera parte de Lucas–Hechos. La identidad del autor, fecha y audiencia exactas son debatidas.','Los relatos de infancia están saturados de Escritura y esperanza de Israel. Jesús participa en sinagoga, fiestas y debates judíos; la inclusión gentil no cancela a Israel.','Un largo viaje a Jerusalén organiza gran parte del evangelio. Banquetes, parábolas, oración y reversión entre alto y bajo aparecen repetidamente.','Dar seguridad sobre la enseñanza recibida y mostrar que la salvación de Dios se manifiesta en misericordia, inclusión y transformación de relaciones y recursos.','El Espíritu impulsa alabanza, misión y cuidado. La buena noticia eleva al humilde sin convertir al poderoso en enemigo deshumanizado.','La designación de Teófilo y el prólogo no prueban estándares historiográficos modernos idénticos. Las parábolas no deben convertirse en biografías de grupos actuales. La inclusión no autoriza apropiarse de Israel o borrar su historia.',ARRAY['Lucas','Espíritu Santo','salvación','pobres','mujeres','samaritanos','Jerusalén']::text[],ARRAY['judíos','samaritanos','gentiles','mujeres','pobres','discípulos']::text[],ARRAY['Galilea','Nazaret','Samaria','Jerusalén']::text[]),
('lucas-1-4-promesa-mision','LUK','section',1,4,'Promesas, cánticos y comienzo de la misión','Anuncios a Zacarías y María, nacimientos, cánticos, presentación, crecimiento, bautismo y tentación culminan cuando Jesús proclama en Nazaret buenas noticias para pobres y liberación.','Herodes, Augusto, censos y autoridades locales sitúan el relato dentro del imperio, aunque los detalles cronológicos del censo de Quirinio son debatidos.','Magníficat, Benedictus y Nunc Dimittis usan lenguaje de salmos y profetas. Simeón y Ana representan esperanza fiel de Israel.','Relatos paralelos de Juan y Jesús conducen a genealogía, prueba y discurso programático en Nazaret.','Presentar la misión como cumplimiento de promesas a Israel orientado a misericordia, libertad y alcance universal.','Dios obra mediante personas jóvenes y mayores, mujeres y hombres, hogares y espacios públicos. La vocación puede comenzar fuera del centro de poder.','El Magníficat no debe reducirse a sentimiento privado; contiene reversión social. La concepción virginal es afirmación teológica y no debe usarse para idealizar pureza corporal o avergonzar a madres.',ARRAY['María','Juan Bautista','cánticos','Nazaret','Espíritu','pobres','liberación']::text[],ARRAY['familia de Jesús','sacerdotes','profetas','pobres']::text[],ARRAY['Nazaret','Belén','Jerusalén','Jordán']::text[]),
('lucas-5-9-galilea','LUK','section',5,9,'Llamado, mesa, compasión e identidad','Jesús llama discípulos, comparte mesa con personas despreciadas, enseña, sana, envía a los Doce y revela su identidad antes de iniciar el viaje a Jerusalén.','Pescadores, cobradores de impuestos, viudas y campesinos habitaban una economía marcada por impuestos, deudas y honor social.','Las comidas expresan inclusión y restauración. La versión lucana de las bienaventuranzas dirige atención directa a pobres y hambrientos.','Historias de llamado y controversia alternan con enseñanza, señales y preguntas sobre identidad hasta confesión y transfiguración.','Mostrar que la misericordia reorganiza la mesa y que el llamado forma una comunidad donde personas previamente excluidas reciben dignidad y responsabilidad.','Recibir perdón no elimina responsabilidad; abre una vida nueva. La compasión no depende del estatus que una sociedad asigna.','La palabra «pecadores» no debe aplicarse como etiqueta deshumanizante. Los milagros no prometen sanidad automática y la pobreza no debe romantizarse como ideal de sufrimiento.',ARRAY['llamado','mesa','pobres','perdón','Doce','transfiguración']::text[],ARRAY['discípulos','cobradores','mujeres','pobres','fariseos']::text[],ARRAY['Galilea','Capernaúm','lago']::text[]),
('lucas-10-19-viaje','LUK','section',10,19,'Viaje a Jerusalén: prójimo, oración y riqueza','Durante el viaje, Jesús envía discípulos, narra parábolas como el samaritano y el hijo perdido, enseña sobre oración, mesa, riqueza, humildad y búsqueda de quien está perdido.','La ruta literaria atraviesa territorios y conflictos de identidad. Samaritanos y judíos compartían Escrituras y una historia de profunda tensión religiosa y política.','Las parábolas dialogan con Torá, profetas y sabiduría judía. El samaritano desafía límites del prójimo; Zaqueo muestra restitución económica.','Una extensa sección propia de Lucas está unida por viaje, comidas, preguntas y parábolas de reversión.','Formar discípulos que reconozcan al prójimo por la misericordia practicada, oren con perseverancia y revisen el uso de recursos.','La conversión tiene consecuencias relacionales y económicas. La humildad no es desprecio propio, sino renuncia a construir valor mediante superioridad.','El samaritano no debe usarse para estereotipar al judaísmo como carente de compasión. El hijo perdido no obliga a reconciliación sin cambio. Las enseñanzas de riqueza no deben vaciarse ni convertirse en promesas de prosperidad.',ARRAY['samaritano','prójimo','Padre nuestro','hijo perdido','riqueza','Zaqueo','Jerusalén']::text[],ARRAY['discípulos','samaritanos','fariseos','ricos','pobres','familias']::text[],ARRAY['Samaria','Jericó','Jerusalén']::text[]),
('lucas-19-24-jerusalen','LUK','section',19,24,'Jerusalén, pasión, Emaús y ascensión','Jesús entra en Jerusalén, lamenta la ciudad, enseña en el templo, comparte la cena, es ejecutado y resucita; en el camino a Emaús interpreta las Escrituras antes de bendecir y enviar a sus seguidores.','La ciudad estaba bajo vigilancia romana durante Pascua. La crucifixión era imperial y la esperanza de restaurar Israel seguía viva entre discípulos.','Lucas subraya inocencia ante acusaciones romanas, oración y perdón. Emaús presenta una lectura de Moisés y Profetas desde el Mesías sufriente, una interpretación cristiana posterior dentro de las Escrituras judías.','La entrada y controversias conducen a pasión; el reconocimiento resucitado ocurre al explicar Escrituras y partir pan.','Mostrar que la salvación atraviesa sufrimiento sin glorificarlo y que la misión nace de Escritura comprendida, hospitalidad y testimonio.','Jesús se acerca a personas decepcionadas, escucha su relato y reorienta su esperanza. El reconocimiento puede surgir en camino y mesa.','La petición de perdón no elimina responsabilidad romana ni sacerdotal. Emaús no autoriza afirmar que el sentido judío previo era falso; presenta una relectura cristiana. La ascensión no implica abandono del mundo.',ARRAY['Jerusalén','Pascua','cena','cruz','Emaús','resurrección','ascensión']::text[],ARRAY['discípulos','autoridades','romanos','mujeres']::text[],ARRAY['Jerusalén','Emaús','Betania']::text[])
)
insert into public.biblical_context_units(slug,book_code,source_id,scope_kind,chapter_start,verse_start,chapter_end,verse_end,title,summary,historical_context,jewish_context,literary_context,authorial_intent,theological_reflection,interpretive_cautions,key_terms,people_groups,places,source_locator,provider_version,content_hash,review_status,enabled,metadata)
select data.slug,data.book_code,source.id,data.scope_kind,data.chapter_start,NULL,data.chapter_end,NULL,data.title,data.summary,data.historical_context,data.jewish_context,data.literary_context,data.authorial_intent,data.theological_reflection,data.interpretive_cautions,data.key_terms,data.people_groups,data.places,'vida://corpus/contexto/evangelios-hechos/v1#'||data.slug,'evangelios-hechos-v1-2026-08-02',encode(extensions.digest(concat_ws('|',data.slug,data.title,data.summary,data.historical_context,data.jewish_context,data.literary_context,data.authorial_intent,data.theological_reflection,data.interpretive_cautions),'sha256'),'hex'),'approved',true,jsonb_build_object('coverage_batch','gospels-acts','generated_by_ai',false,'review_level','editorial')
